(ns seon.web.js
  "Lightweight progressive browser controllers (sticky tail-scroll, debounced viewport sync,
   and native popover=hint + CSS Anchor Positioning hovercard controller). Zero CDN dependencies.")

(def sticky-scroll-js
  "Targeted Datastar tail-scroll + composer auto-grow controller (WeakMap state, datastar-fetch + activeViewTransition hook, batched rAF read/write, ResizeObserver on expanding view/stream boxes, zero MutationObserver)."
  (str "(()=>{"
       "const A='.stage-scroll,.ws-timeline,.live-drawer-body,.live-reasoning,.live-prose,.stream-dock',"
       "V='.stage-scroll,.ws-timeline',"
       "S='.live-drawer-body,.live-reasoning,.live-prose,.stream-dock',"
       "P={capture:true,passive:true},st=new WeakMap(),rs=new WeakSet(),"
       "on=(t,f,o=P)=>document.addEventListener(t,f,o);"
       "let raf=0,mk=0,ty=null,te=null;"
       "const grow=(t)=>{if(!t||!t.classList||!t.classList.contains('composer-inp'))return;t.style.height='auto';t.style.height=Math.min(220,Math.max(30,t.scrollHeight))+'px';};"
       "const dbg=(e)=>e.classList.contains('stage-scroll')&&!!e.querySelector('.debug-wrap');"
       "const vm=(e)=>{const v=e.classList.contains('stage-scroll')?e.querySelector('#seon-view-unit'):null;return v?(v.dataset.viewMode||''):'';};"
       "const isCv=(e)=>e.classList.contains('stage-scroll')&&vm(e)==='canvas';"
       "const liveCv=(e)=>!!e.querySelector('#cv-pending,#cv-live-prose');"
       "const ck=(e)=>{if(e.classList.contains('stage-scroll')){const v=e.querySelector('#seon-view-unit');return v?(v.dataset.agent||'')+':'+(v.dataset.viewMode||'')+':'+(v.dataset.expertMode||''):'';}return(e.dataset.agent||'')+':'+(e.id||'');};"
       "const gs=(e)=>{let s=st.get(e);if(!s){const cv=isCv(e),lv=cv?liveCv(e):false,pin=dbg(e)?false:(cv?lv:true);s={pin,live:lv,top:e.scrollTop,max:0,pu:0,uu:0,born:performance.now(),ctx:ck(e)};st.set(e,s);}return s;};"
       "const ro=typeof ResizeObserver==='function'?new ResizeObserver((es)=>{let m=0;for(const x of es){const t=x.target;if(t&&(t.id==='seon-view-unit'||t.id==='cv-canvas-stage'||t.id==='cv-pending'||t.id==='cv-live-prose'||t.id==='cv-featured-reply'||t.classList.contains('ws-timeline')||(t.parentElement&&t.parentElement.classList.contains('ws-timeline'))))m|=1;else m|=2;}if(m)sched(m);}):null;"
       "const obs=(n)=>{if(ro&&n&&!rs.has(n)){rs.add(n);ro.observe(n);}};"
       "const snap=()=>{raf=0;const m=mk;mk=0;const els=document.querySelectorAll(m===1?V:m===2?S:A),now=performance.now(),wr=[];if(ro){['#seon-view-unit','#cv-canvas-stage','#cv-pending','#cv-live-prose','#cv-featured-reply'].forEach((q)=>obs(document.querySelector(q)));}for(const e of els){if(e.classList.contains('ws-timeline')){obs(e);for(const ch of e.children)obs(ch);}else if(e.classList.contains('live-drawer-body')||e.classList.contains('live-reasoning')||e.classList.contains('live-prose'))obs(e);const s=gs(e),c=ck(e);if(dbg(e)){if(s.ctx!==c){s.ctx=c;s.pin=false;s.live=false;wr.push([e,s,0,0]);}continue;}const cv=isCv(e);if(cv){const lv=liveCv(e);if(s.ctx!==c){s.ctx=c;s.live=lv;s.uu=0;if(lv)s.pin=true;else{s.pin=false;wr.push([e,s,0,0]);continue;}}else if(lv&&!s.live){s.live=true;s.pin=true;s.uu=0;}else if(!lv&&s.live){s.live=false;}}else if(s.ctx!==c){s.ctx=c;s.pin=true;s.live=false;s.uu=0;}const mx=Math.max(0,e.scrollHeight-e.clientHeight);if(s.pin&&mx>0&&Math.abs(mx-e.scrollTop)>1)wr.push([e,s,mx,mx]);else s.max=mx;}for(const[e,s,t,mx]of wr){s.pu=now+140;s.top=t;s.max=mx;e.scrollTop=t;}};"
       "const sched=(m)=>{mk|=m;if(!raf)raf=requestAnimationFrame(snap);};"
       "const resnap=(m)=>{sched(m);const hookVt=()=>{const vt=document.activeViewTransition;if(vt&&vt.updateCallbackDone){vt.updateCallbackDone.then(()=>{sched(m);requestAnimationFrame(()=>sched(m));}).catch(()=>{});}if(vt&&vt.finished){vt.finished.then(()=>{sched(m);requestAnimationFrame(()=>sched(m));}).catch(()=>{});}};hookVt();if(typeof queueMicrotask==='function')queueMicrotask(hookVt);requestAnimationFrame(()=>{hookVt();sched(m);});setTimeout(()=>sched(m),40);setTimeout(()=>sched(m),260);};"
       "const ft=(n)=>n&&n.closest?n.closest(A):null;"
       "const fs=(n)=>{let e=ft(n);while(e){if(e.scrollHeight>e.clientHeight+1)return e;e=ft(e.parentElement);}return ft(n);};"
       "on('input',(e)=>grow(e.target));"
       "on('wheel',(e)=>{const el=fs(e.target);if(!el)return;const s=gs(el);if(e.deltaY<0){s.pin=false;s.uu=performance.now()+250;}else if(e.deltaY>0)s.uu=0;});"
       "on('touchstart',(e)=>{if(e.touches&&e.touches.length===1){ty=e.touches[0].clientY;te=fs(e.target);}});"
       "on('touchmove',(e)=>{if(te&&ty!==null&&e.touches&&e.touches.length===1){const dy=e.touches[0].clientY-ty;if(dy>4){const s=gs(te);s.pin=false;s.uu=performance.now()+250;}else if(dy<-4)gs(te).uu=0;}});"
       "on('keydown',(e)=>{if(e.key==='ArrowUp'||e.key==='PageUp'||e.key==='Home'){const t=e.target&&e.target.tagName;if(t==='INPUT'||t==='TEXTAREA')return;const el=fs(e.target)||document.getElementById('seon-main');if(el){const s=gs(el);s.pin=false;s.uu=performance.now()+250;}}});"
       "on('scroll',(e)=>{const el=e.target;if(!el||!el.matches||!el.matches(A)||dbg(el))return;const s=gs(el),top=el.scrollTop,mx=Math.max(0,el.scrollHeight-el.clientHeight),d=mx-top,now=performance.now();if(top<s.top-0.5)s.pin=false;else if(now>=s.pu){if(d<=24&&now>=s.uu)s.pin=true;else if(Math.abs(mx-s.max)<=1&&d>24)s.pin=false;}s.top=top;s.max=mx;});"
       "on('toggle',(e)=>{const d=e.target;if(!d||d.tagName!=='DETAILS'||!d.open)return;const el=ft(d.parentElement);if(!el||dbg(el))return;const s=gs(el),now=performance.now();if(now<s.born+400||now<s.pu)return;if(el.scrollHeight-el.clientHeight-el.scrollTop>24)s.pin=false;});"
       "on('submit',(e)=>{const f=e.target;if(f&&f.querySelectorAll){f.querySelectorAll('.composer-inp').forEach((t)=>{setTimeout(()=>{t.style.height='';},0);});}document.querySelectorAll(A).forEach((el)=>{if(!dbg(el)){const s=gs(el);s.pin=true;s.uu=0;}});sched(3);},true);"
       "on('datastar-fetch',(e)=>{const d=e&&e.detail;if(!d||d.type!=='datastar-patch-elements')return;const r=d.argsRaw&&d.argsRaw.elements;if(typeof r==='string'){let m=0;if(r.includes('seon-view-unit')||r.includes('ws-left-unit'))m|=1;if(r.includes('seon-stream-unit'))m|=2;if(m){if(m&1)resnap(m);else sched(m);}}else resnap(3);},false);"
       "on('click',(e)=>{const b=e.target&&e.target.closest&&e.target.closest('.stream-phase-pill,.thinking-toggle');if(b&&!b.classList.contains('is-close')){document.querySelectorAll(S).forEach((el)=>{const s=gs(el);s.pin=true;s.uu=0;});sched(2);}});"
       "window.addEventListener('resize',()=>sched(3),{passive:true});window.addEventListener('popstate',()=>resnap(1),{passive:true});"
       "const init=()=>{document.querySelectorAll('.composer-inp').forEach(grow);sched(3);requestAnimationFrame(()=>sched(3));};"
       "if(document.readyState==='loading')window.addEventListener('DOMContentLoaded',init,{once:true});else init();"
       "window.addEventListener('load',()=>{sched(3);requestAnimationFrame(()=>sched(3));},{once:true});"
       "})();"))

(def viewport-sync-js
  "Debounced (180 ms) browser viewport sync posting `(seon.web/set-viewport! w h)` on initial load and resize, guarded against headless `seon-browser` previews."
  "(()=>{let t=0,lw=0,lh=0,ac=null;const send=()=>{if(window.__seonPreviewBusy||location.hash==='#seon-headless'||document.getElementById('seon-preview-stage'))return;const w=Math.max(200,Math.min(10000,Math.round(window.innerWidth||0))),h=Math.max(200,Math.min(10000,Math.round(window.innerHeight||0)));if(w===lw&&h===lh)return;lw=w;lh=h;if(ac)ac.abort();ac=typeof AbortController==='function'?new AbortController():null;fetch('/call?form='+encodeURIComponent('(seon.web/set-viewport! '+w+' '+h+')'),ac?{method:'POST',signal:ac.signal}:{method:'POST'}).catch((e)=>{if(!e||e.name!=='AbortError'){}});},sched=()=>{clearTimeout(t);t=setTimeout(send,180);};window.addEventListener('resize',sched,{passive:true});if(document.readyState==='loading')window.addEventListener('DOMContentLoaded',send,{once:true});else send();})();")

(def hovercard-js
  "Progressive hovercard controller: native popover=hint + interestfor, 180ms hover show / 140ms hoverable leave grace (WCAG 1.4.13), keyboard focus without focus theft (WCAG 3.2.1), Escape/click dismiss, Map cache (0ms repeat hovers), CSS Anchor Positioning with getBoundingClientRect fallback."
  (str "(()=>{"
       "const cache=new Map();"
       "let hc=null,trig=null,showT=0,hideT=0,ac=null,setAria=false;"
       "const card=()=>hc||(hc=document.getElementById('seon-hovercard'));"
       "const hasAnchor=()=>typeof CSS!=='undefined'&&CSS.supports&&CSS.supports('position-area','block-end');"
       "const clearT=()=>{clearTimeout(showT);clearTimeout(hideT);showT=hideT=0;};"
       "const hide=()=>{"
       "clearT();if(ac){ac.abort();ac=null;}"
       "const p=card();"
       "if(trig){if(setAria){trig.removeAttribute('aria-describedby');setAria=false;}if(hasAnchor())trig.style.anchorName='';}"
       "trig=null;"
       "if(p){try{p.hidePopover();}catch(_){p.removeAttribute('data-open');}}"
       "};"
       "const place=(el,p)=>{"
       "if(hasAnchor()){el.style.anchorName='--seon-hc';p.style.positionAnchor='--seon-hc';p.style.position='';p.style.left='';p.style.top='';return;}"
       "const r=el.getBoundingClientRect(),w=Math.min(360,window.innerWidth-24);"
       "const x=Math.max(12,Math.min(window.innerWidth-w-12,r.left));"
       "const y=r.bottom+6+180>window.innerHeight?Math.max(12,r.top-186):r.bottom+6;"
       "p.style.position='fixed';p.style.left=x+'px';p.style.top=y+'px';"
       "};"
       "const show=(el)=>{"
       "const ref=el&&el.getAttribute('data-preview-ref'),p=card();"
       "if(!ref||!p)return;"
       "if(trig&&trig!==el){if(setAria){trig.removeAttribute('aria-describedby');setAria=false;}if(hasAnchor())trig.style.anchorName='';}"
       "trig=el;"
       "if(!el.hasAttribute('aria-describedby')){el.setAttribute('aria-describedby','seon-hovercard');setAria=true;}"
       "const render=(html)=>{if(trig!==el)return;p.innerHTML=html;place(el,p);try{p.showPopover();}catch(_){p.setAttribute('data-open','1');}};"
       "if(cache.has(ref)){const h=cache.get(ref);if(h)render(h);else if(trig===el){if(setAria){el.removeAttribute('aria-describedby');setAria=false;}trig=null;}return;}"
       "if(ac)ac.abort();ac=typeof AbortController==='function'?new AbortController():null;"
       "fetch('/preview?ref='+encodeURIComponent(ref),ac?{signal:ac.signal}:{}).then((r)=>r.ok?r.text():'').then((html)=>{"
       "if(cache.size>128)cache.clear();cache.set(ref,html||'');if(!html){if(trig===el){if(setAria){el.removeAttribute('aria-describedby');setAria=false;}trig=null;}return;}render(html);"
       "}).catch(()=>{});"
       "};"
       "const findTrig=(n)=>n&&n.closest&&!n.closest('#seon-hovercard')?n.closest('[data-preview-ref]'):null;"
       "document.addEventListener('pointerover',(e)=>{const el=findTrig(e.target);if(el){clearTimeout(hideT);if(trig===el)return;clearTimeout(showT);showT=setTimeout(()=>show(el),180);}else if(e.target&&e.target.closest&&e.target.closest('#seon-hovercard')){clearTimeout(hideT);}},true);"
       "document.addEventListener('pointerout',(e)=>{if(findTrig(e.target)||(e.target&&e.target.closest&&e.target.closest('#seon-hovercard'))){clearTimeout(showT);clearTimeout(hideT);hideT=setTimeout(hide,140);}},true);"
       "document.addEventListener('focusin',(e)=>{const el=findTrig(e.target);if(el){clearT();show(el);}},true);"
       "document.addEventListener('focusout',(e)=>{if(findTrig(e.target)){clearT();hideT=setTimeout(hide,120);}},true);"
       "document.addEventListener('keydown',(e)=>{if(e.key==='Escape')hide();},true);"
       "document.addEventListener('click',(e)=>{if(findTrig(e.target))hide();},true);"
       "document.addEventListener('datastar-fetch',(e)=>{const d=e&&e.detail;if(d&&d.type==='datastar-patch-elements'&&typeof(d.argsRaw&&d.argsRaw.elements)==='string'&&(d.argsRaw.elements.includes('seon-view-unit')||d.argsRaw.elements.includes('seon-header')||d.argsRaw.elements.includes('seon-sidebar')))cache.clear();});"
       "})();"))
